---@class PatrolChoosePanelEventCell
---@field Txt                           	UnityEngine.UI.Text
---@field ImgIcon                       	Engine.UI.RawImageAlterable
---@field AnimRoot                      	UnityEngine.RectTransform
local PatrolChoosePanelEventCell = Class("PatrolChoosePanelEventCell")
function PatrolChoosePanelEventCell:__init()
    self.btnAction = nil
    self.data = nil
    self.isSelect = nil
end

function PatrolChoosePanelEventCell:__delete()
    self.btnAction = nil
    self.data = nil
    self.isSelect = nil

    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function PatrolChoosePanelEventCell:SetBtnCallBack(cb)
    self.btnAction = cb
end

function PatrolChoosePanelEventCell:Awake()
    MazeMgr = import('Game.Maze.MazeMgr'):GetInstance()
    self.EventEnterEvent = Events.AddListener(Constants.EventNames.PatrolEventEnter, Bind(self, self.FreshSelectStatus))
    self.EventEnterChoose = Events.AddListener(Constants.EventNames.PatrolEventChoose, Bind(self, self.PlayChooseAnim))

    SetButtonAction(self.controller, function ()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)
end

function PatrolChoosePanelEventCell:FreshBaseUI(data)
    self.data = data
    self.Txt.text = self.data.text
    --self.ImgIcon:LoadSprite(self.data.iconPath)
    self:FreshSelectStatus()

end

function PatrolChoosePanelEventCell:FreshSelectStatus()
    if isNull(self.data) then
        return
    end
    local hasSelected = MazeMgr.currentPos > 0
    if hasSelected then
        self.co = cs_coroutine.start(function()
            cs_coroutine.yield_return(Yielders.EndOfFrame)
            self:PlayChooseAnim(MazeMgr.currentPos)
        end)
    end
end

function PatrolChoosePanelEventCell:PlayChooseAnim(index)
    --local hasSelected = MazeMgr.currentPos > 0
    --if (isNull(index) or isNull(self.data)) then
    --    CfUtils.PlayAnimator(self.AnimRoot, "Default")
    --    return
    --end
    if isNull(index) then
        self.isSelect = nil
        index = MazeMgr.currentPos
        local hasSelected = MazeMgr.currentPos > 0
        if not hasSelected then
            CfUtils.PlayAnimator(self.AnimRoot, "Default")
            return
        end
    end

    local isSelect = (index == self.data.index)
    if isSelect ~= self.isSelect then
        local animName = isSelect and "Choose" or "Cancel"
        CfUtils.PlayAnimator(self.AnimRoot, animName)
    end
    self.isSelect = isSelect
end


function PatrolChoosePanelEventCell:OnDestroy()
    Events.RemoveListener(Constants.EventNames.PatrolEventEnter, self.EventEnterEvent)
    Events.RemoveListener(Constants.EventNames.PatrolEventChoose, self.EventEnterChoose)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PatrolChoosePanelEventCell